def gaps(postings):
    result = []
    if len(postings) > 0:
        result.append(postings[0])
        for i in range(1, len(postings)):
            diff = postings[i] - postings[i-1]
            result.append(diff)
    return result

def vb_encode(n):
    bytes = []
    while True:
        bytes.insert(0, n % 128)
        n = n // 128
        if n == 0:
            break
    bytes[-1] = bytes[-1] + 128
    return bytes

def vb_encode_list(postings):
    gapped = gaps(postings)
    all_bytes = []
    for num in gapped:
        encoded = vb_encode(num)
        for b in encoded:
            all_bytes.append(b)
    return all_bytes

def vb_decode(bytes_list):
    numbers = []
    current_n = 0
    for b in bytes_list:
        if b < 128:
            current_n = 128 * current_n + b
        else:
            current_n = 128 * current_n + (b - 128)
            numbers.append(current_n)
            current_n = 0
    return numbers

print(vb_encode(130))

